package dev.eigenworks.computer.accelerator;
import dev.eigenworks.block.entity.AdvancedEngineeringConsoleBlockEntity;import dev.eigenworks.registry.ModMenus;import net.minecraft.world.entity.player.*;import net.minecraft.world.inventory.*;import net.minecraft.world.item.ItemStack;
public final class AdvancedConsoleMenu extends AbstractContainerMenu{public static final int DATA_COUNT=6;private final ContainerData data;private final AdvancedEngineeringConsoleBlockEntity console;public AdvancedConsoleMenu(int id,Inventory i){this(id,new SimpleContainerData(DATA_COUNT),null);}public AdvancedConsoleMenu(int id,AdvancedEngineeringConsoleBlockEntity c){this(id,c.menuData(),c);}private AdvancedConsoleMenu(int id,ContainerData d,AdvancedEngineeringConsoleBlockEntity c){super(ModMenus.ADVANCED_CONSOLE,id);data=d;console=c;checkContainerDataCount(d,DATA_COUNT);addDataSlots(d);}@Override public ItemStack quickMoveStack(Player p,int s){return ItemStack.EMPTY;}@Override public boolean stillValid(Player p){return console==null||console.stillValid(p);}@Override public boolean clickMenuButton(Player p,int id){if(console==null||!stillValid(p))return false;switch(id){case 0->console.nextModule();case 1->console.runDiagnostic();case 2->console.nextBitrate();case 3->console.nextLatency();case 4->console.nextDamping();default->{return false;}}return true;}public int module(){return data.get(0);}public int bitrate(){return data.get(1);}public int latencyMs(){return data.get(2);}public double damping(){return data.get(3)/1000.0;}public int cycles(){return data.get(4);}public boolean successful(){return data.get(5)!=0;}}
